'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 153.0,
  "height": 149.0,
  "autosize": {
    "type": "pad"
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "strokeWidth": 3,
        "strokeCap": "round",
        "opacity": 0.6
      },
      "encoding": {
        "y": {
          "field": "Booking Channel",
          "type": "nominal",
          "sort": {
            "field": "Baseline No-show Rate",
            "op": "max",
            "order": "descending"
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "Baseline No-show Rate"
        },
        "x2": {
          "datum": 0
        },
        "color": {
          "condition": {
            "test": "datum[''Booking Channel''] == ''Walk-in''",
            "value": "#EB6834"
          },
          "value": "#F4B393"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 150,
        "opacity": 1,
        "stroke": "white",
        "strokeWidth": 2
      },
      "encoding": {
        "y": {
          "field": "Booking Channel",
          "type": "nominal",
          "sort": {
            "field": "Baseline No-show Rate",
            "op": "max",
            "order": "descending"
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "Baseline No-show Rate"
        },
        "color": {
          "condition": {
            "test": "datum[''Booking Channel''] == ''Walk-in''",
            "value": "#EB6834"
          },
          "value": "#F4B393"
        },
        "tooltip": [
          {
            "field": "Booking Channel"
          },
          {
            "field": "Baseline No-show Rate",
            "format": ".1%"
          },
          {
            "field": "Baseline Eligible Appointments",
            "format": ","
          }
        ]
      }
    },
    {
      "transform": [
        {
          "calculate": "format(datum[''Baseline No-show Rate''], ''.1%'')",
          "as": "r"
        },
        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "Baseline No-show Rate",
              "as": "mx"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 16,
        "fontSize": 10.5,
        "fontWeight": 600,
        "color": "#101828"
      },
      "encoding": {
        "y": {
          "field": "Booking Channel",
          "type": "nominal",
          "sort": {
            "field": "Baseline No-show Rate",
            "op": "max",
            "order": "descending"
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "mx"
        },
        "text": {
          "field": "r"
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "''n='' + format(datum[''Baseline Eligible Appointments''], '','')",
          "as": "n"
        },
        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "Baseline No-show Rate",
              "as": "mx"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 58,
        "fontSize": 9,
        "color": "#667085"
      },
      "encoding": {
        "y": {
          "field": "Booking Channel",
          "type": "nominal",
          "sort": {
            "field": "Baseline No-show Rate",
            "op": "max",
            "order": "descending"
          },
          "title": null,
          "axis": {
            "labelColor": "#344054",
            "labelFontSize": 10.5
          }
        },
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "mx"
        },
        "text": {
          "field": "n"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "max",
              "field": "All-clinic Baseline No-show Rate",
              "as": "net"
            }
          ]
        }
      ],
      "mark": {
        "type": "rule",
        "strokeDash": [
          4,
          3
        ],
        "color": "#344054",
        "opacity": 0.55
      },
      "encoding": {
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "net"
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "max",
              "field": "All-clinic Baseline No-show Rate",
              "as": "net"
            }
          ]
        },
        {
          "calculate": "''all-clinic avg '' + format(datum.net, ''.1%'')",
          "as": "lab"
        }
      ],
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "bottom",
        "dy": -2,
        "fontSize": 9,
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              0.2
            ]
          },
          "axis": null,
          "field": "net"
        },
        "y": {
          "value": 0
        },
        "text": {
          "field": "lab"
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
